import React, { useState } from 'react';

// Define the Notification interface here
interface Notification {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
}

// Create the NotificationSystem component here
const NotificationSystem = () => {
  // Initialize notifications state here
  const [notifications, setNotifications] = useState<Notification[]>([
    { id: 1, message: 'System update available', type: 'info' },
    { id: 2, message: 'Low disk space warning', type: 'warning' },
    { id: 3, message: 'Connection failed', type: 'error' }
  ]);

  // Create addNotification handler here
  const addNotification = (message: string, type: Notification['type']) => {
    const newNotification: Notification = {
      id: Date.now(),
      message,
      type
    };
    setNotifications(prev => [...prev, newNotification]);
  };

  // Create markAsRead handler here
  const markAsRead = (id: number) => {
    setNotifications(prev => prev.filter(notification => notification.id !== id));
  };

  // Create clearAllNotifications handler here
  const clearAllNotifications = () => {
    setNotifications([]);
  };

  return (
    <div>
      <h1>Notification System</h1>
      <div>
        <h2>Notifications</h2>
        <button onClick={clearAllNotifications}>Clear All</button>
      </div>
      <ul>
        {notifications.map(notification => (
          <li key={notification.id}>
            <span>[{notification.type}] {notification.message}</span>
            {/* Add mark as read button here */}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default NotificationSystem;

